<script setup lang="ts">
import {computed,ref} from 'vue';
import {state,modal,selectedItem,dispatch,openGuide} from './store';
import {ITEMS,EQUIPMENT} from '../content';
import {rootCapacity} from '../game/engine';
import {energyEligible,energyPlan,energyTest,energyReturnPosition,ENERGY_PROFILES,ENERGY_LOADS} from '../game/energy';
import type {EnergyProfileId,EnergyLoad} from '../game/types';
import Art from './Art.vue';
import DeliveryHints from './DeliveryHints.vue';
const profile=ref<EnergyProfileId>('economy'),load=ref<EnergyLoad>('steady'),reading=ref(0);
const goods=computed(()=>state.value.items.filter(i=>i.owner==='player'&&energyEligible(i)));
const work=computed(()=>state.value.energyWork);
const item=computed(()=>goods.value.find(i=>i.id===(work.value?.itemId??selectedItem.value))??goods.value.find(i=>!i.energyPreparation)??goods.value[0]);
const definition=computed(()=>ITEMS.find(d=>d.id===item.value?.definitionId));
const plans=computed(()=>ENERGY_PROFILES.map(p=>energyPlan(state.value,item.value,p.id)));
const plan=computed(()=>plans.value.find(p=>p.profile?.id===profile.value)!);
const test=computed(()=>item.value?energyTest(item.value):undefined);
const known=computed(()=>item.value?.known.some(k=>['scan','batch'].includes(k)));
const basic=computed(()=>item.value?.known.some(k=>['basic','diagnosed'].includes(k)));
const returnFits=computed(()=>energyReturnPosition(state.value,rootCapacity(state.value)));
function start(){if(item.value&&dispatch({type:'startEnergy',itemId:item.value.id,profileId:profile.value})){load.value='steady';reading.value=0;}}
function finish(){const id=item.value?.id;if(id&&dispatch({type:'finishEnergy'}))selectedItem.value=id;}
const name=(id:string)=>ITEMS.find(d=>d.id===id)?.name??id;
</script>
<template>
 <div class="energy-bench">
  <header class="energy-heading"><div><p class="eyebrow">ENERGY / 储能整备</p><h2>把余量，留给下一盏灯。</h2></div><div><button @click="modal='inventory'">返回库存 ↗</button><button @click="openGuide('repair')">工位手册 ?</button></div></header>
  <div class="energy-stock" aria-label="可选储能货物"><button v-for="good in goods" :key="good.id" :data-energy-item="good.id" :class="{selected:item?.id===good.id}" :disabled="!!work&&good.id!==work.itemId" @click="selectedItem=good.id"><Art :id="good.definitionId"/><span>{{name(good.definitionId)}}<small>{{good.energyPreparation?'已整备':good.known.some(k=>['scan','batch'].includes(k))?`容量 ${good.capacity}%`:'容量待检查'}} · 成本 ₡{{good.cost}}</small></span></button></div>
  <p v-if="!item" class="energy-empty">先从卖家买入标准电池组、微型电容阵列或便携电源模块，再收进仓库。</p>
  <template v-else-if="definition">
   <div class="energy-work-grid">
    <section class="energy-rig" aria-label="储能工位"><div class="energy-rig-title"><span>{{work?work.verified?'负载稳定':'等待负载复核':item.energyPreparation?'已完成整备':'待装夹'}}</span><small>{{definition.name}}</small></div><div class="energy-object"><div class="energy-rails"></div><Art :id="item.definitionId" :label="definition.name" eager/><div class="energy-socket negative">−</div><div class="energy-socket positive">＋</div></div><div class="energy-gauge"><span>有效容量</span><strong>{{known?`${item.capacity}%`:'—'}}</strong><div class="energy-gauge-track"><i :style="{width:known?`${item.capacity}%`:'0%'}"></i><b v-if="work&&!work.verified" :style="{left:`${work.target}%`}"></b></div><small v-if="work">整备目标 {{work.target}}% · {{ENERGY_PROFILES.find(p=>p.id===work?.profileId)?.name}}</small><small v-else-if="item.energyPreparation">第 {{item.energyPreparation.day}} 日 · {{item.energyPreparation.before}}% → {{item.energyPreparation.after}}%</small><small v-else>累计成本 ₡{{item.cost}}</small></div></section>
    <section class="energy-controls" aria-label="能源操作">
     <template v-if="work&&test">
      <p class="eyebrow">LOAD TEST / 铭牌要求</p><h3>{{ENERGY_LOADS.find(l=>l.id===test?.load)?.name}}</h3><p class="energy-reference">参考读数 <strong>{{test.value}}</strong><small>允许 ±2 · 每次复核 0.5 h</small></p>
      <template v-if="!work.verified"><div class="energy-loads" role="group" aria-label="复核负载"><button v-for="mode in ENERGY_LOADS" :key="mode.id" :aria-pressed="load===mode.id" :class="{selected:load===mode.id}" @click="load=mode.id">{{mode.name}}</button></div><label class="energy-reading">参考读数<input v-model.number="reading" type="number" min="0" max="100" step="1" aria-label="设置参考读数"/></label><input v-model.number="reading" class="energy-slider" type="range" min="0" max="100" step="1" aria-label="调整参考读数"/><p v-if="work.attempts" class="energy-retry">上次复核未通过 · 已测试 {{work.attempts}} 次</p><button class="primary energy-run" :disabled="state.phase!=='open'||state.hours<.5" @click="dispatch({type:'verifyEnergy',load,value:reading})">接入负载并复核</button><p v-if="state.phase!=='open'||state.hours<.5" class="energy-note">工单已保留，明天开店后继续。</p></template>
      <template v-else><p class="energy-passed">✓ 复核通过<br/><small>有效容量 {{work.before}}% → {{work.target}}%</small></p><button class="primary energy-run" :disabled="!returnFits" @click="finish">收回货架 →</button><p v-if="!returnFits" class="energy-note">仓库缺少连续空位。先整理，货物留在工位。</p></template>
      <p class="energy-note">本次已投入 ₡{{work.electricity+work.materialCost}} · 工时 {{work.processHours+work.attempts*.5}} h</p>
     </template>
     <template v-else-if="item.energyPreparation"><p class="eyebrow">PREPARATION RECORD / 整备记录</p><h3>这件货，已经准备好了。</h3><p class="energy-note">电费 ₡{{item.energyPreparation.electricity}} · 耗材成本 ₡{{item.energyPreparation.materialCost}}<br/>总工时 {{item.energyPreparation.hours}} h · 累计成本 ₡{{item.cost}}</p><DeliveryHints :item="item"/><button class="energy-run" @click="modal='inventory'">回库存安排去向 ↗</button></template>
     <template v-else><p class="eyebrow">PLAN / 确认投入</p><h3>{{plan.profile?.name}}</h3><template v-if="known"><p class="energy-target">{{plan.before}}% <span>→</span> {{Math.max(plan.before??0,plan.target??0)}}%</p><p class="energy-note">整备 {{plan.hours}} h + 复核 0.5 h<br/>电费 ₡{{plan.electricity}}<template v-if="plan.material"><br/>{{plan.material.name}} × 1 · 已购成本 ₡{{plan.materialCost}}</template><br/>累计成本 → ₡{{item.cost+plan.cost}}</p></template><p class="energy-once">每件只可整备一次。确认后结算投入，完成负载复核后收回货架。</p><p v-if="!plan.ok" class="energy-blocked">{{plan.reason}}</p><button v-if="!basic" @click="dispatch({type:'inspect',itemId:item.id,method:'basic'})">检查品相与功能</button><button v-else-if="!known&&state.equipment.scanner" @click="dispatch({type:'inspect',itemId:item.id,method:'scan'})">扫描有效容量</button><button v-if="!state.equipment.scanner||(plan.profile?.tool&&!state.equipment[plan.profile.tool])||(plan.material&&!plan.stock)" @click="modal='equipment'">采购所需工具或耗材 ↗</button><button class="primary energy-run" :disabled="!plan.ok" @click="start">{{known?`确认整备 · ₡${plan.cost}`:'先核对货品'}}</button></template>
    </section>
   </div>
   <div v-if="!work&&!item.energyPreparation" class="energy-profiles" aria-label="选择整备方案"><button v-for="p in plans" :key="p.profile!.id" :data-energy-profile="p.profile!.id" :aria-pressed="profile===p.profile!.id" :class="{selected:profile===p.profile!.id}" @click="profile=p.profile!.id"><strong>{{p.profile!.name}}</strong><span v-if="known">{{Math.max(p.before??0,p.target??0)}}% · {{p.hours}} h · ₡{{p.cost}}</span><span v-else>最高 {{p.profile!.target}}% · 最多提升 {{p.profile!.gain}} 点</span><small>{{p.profile!.description}}<template v-if="p.profile!.material"> {{EQUIPMENT.find(e=>e.id===p.profile!.material)?.name}} × 1。</template><template v-if="p.profile!.tool"> 需精密校准仪。</template></small></button></div>
  </template>
 </div>
</template>
<style scoped>
.energy-bench{padding:32px 36px;color:#d5dfce}.energy-heading{display:flex;justify-content:space-between;gap:18px;align-items:center}.energy-heading h2{font-size:26px;font-weight:400;margin:9px 0}.energy-heading>div:last-child{display:flex;gap:12px}.energy-heading button{font-size:11px;background:transparent;border:0;border-bottom:1px solid #839583;padding:6px 0}.energy-stock{display:flex;gap:8px;overflow:auto;margin:24px 0 18px;padding-bottom:7px}.energy-stock button{display:flex;align-items:center;gap:10px;text-align:left;min-width:205px;padding:9px 12px;background:#1c3835;border:1px solid #547067}.energy-stock button.selected{border-color:#d1b77d;background:#354a3b}.energy-stock img{width:42px;height:42px;object-fit:contain}.energy-stock span{font-size:12px}.energy-stock small{display:block;font-size:10px;color:#b2c2ac;margin-top:6px}.energy-work-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:24px}.energy-rig{background:repeating-linear-gradient(0deg,#263935 0px,#263935 2px,#2a3e38 3px,#2a3e38 5px);border:7px double #566b60;box-shadow:inset 0 0 30px #091817;padding:18px;min-width:0}.energy-rig-title{display:flex;justify-content:space-between;border-bottom:1px solid #5b7166;padding-bottom:12px;gap:10px;font-size:12px;color:#d6c59b}.energy-rig-title small{font-size:10px;color:#a8c1b0}.energy-object{position:relative;height:210px;display:flex;align-items:center;justify-content:center}.energy-object>img{position:relative;width:70%;height:180px;object-fit:contain;filter:drop-shadow(7px 10px 8px #091716aa);z-index:1}.energy-rails{position:absolute;inset:35px 14%;border:7px ridge #6d7b6c;border-top:0;border-bottom:0;background:linear-gradient(90deg,transparent 48%,#1a2825 48%,#1a2825 52%,transparent 52%)}.energy-socket{position:absolute;bottom:4px;border:3px solid #b6ad8d;border-radius:50%;width:23px;height:23px;display:grid;place-items:center;background:#354039;color:#d6d8b2;font-size:14px}.energy-socket.negative{left:16%;box-shadow:0 8px 0 #12201e}.energy-socket.positive{right:16%;background:#6a3d35;box-shadow:0 8px 0 #342622}.energy-gauge{margin-top:20px;padding:16px 19px;background:#081e20;border:2px inset #61786c}.energy-gauge>span{font-size:11px;color:#a9c0ab}.energy-gauge>strong{float:right;font-size:23px;font-weight:400;color:#cfdb9c}.energy-gauge-track{position:relative;background:#243f39;height:10px;margin:19px 0 9px}.energy-gauge-track i{display:block;background:#b4c98b;height:100%;transition:width .4s}.energy-gauge-track b{position:absolute;height:20px;top:-5px;border-left:2px solid #d2ad71}.energy-gauge small{font-size:10px;color:#acbd9d}.energy-controls{padding:18px 0}.energy-controls h3{font-size:19px;font-weight:400;margin:9px 0 18px}.energy-controls button{font-size:12px}.energy-target{font-size:30px;color:#ddc795}.energy-target span{color:#7b9c8b;padding:0 12px}.energy-note,.energy-once{font-size:12px;line-height:1.9;color:#b8c9b4}.energy-once{padding-top:12px;border-top:1px dashed #657d64;margin-top:14px;font-size:11px;color:#cbbd9a}.energy-run{width:100%;margin-top:15px;min-height:42px}.energy-blocked,.energy-retry{font-size:12px;color:#e0b394;line-height:1.8}.energy-profiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px;margin-top:22px}.energy-profiles button{text-align:left;background:#1c3734;border:1px solid #5a7868;padding:17px 18px}.energy-profiles button.selected{background:#3a4c39;border-color:#d1bb83;box-shadow:inset 3px 0 #d1bb83}.energy-profiles strong{font-size:14px;font-weight:400;display:block;color:#e0d1ad}.energy-profiles span{font-size:13px;display:block;margin-top:9px;color:#c4d5b2}.energy-profiles small{font-size:11px;display:block;margin-top:9px;line-height:1.7;color:#b1c0ad}.energy-reference{font-size:12px}.energy-reference strong{font-size:30px;color:#dfd7ad;margin-left:8px;font-weight:400}.energy-reference small{font-size:10px;display:block;color:#acbfa6;margin-top:8px}.energy-loads{display:flex;gap:6px;margin:20px 0 16px}.energy-loads button{flex:1;padding:9px 4px;font-size:11px;background:#203c36;border:1px solid #68836d}.energy-loads button.selected{color:#e4deb7;border-color:#c6bb89;background:#42563b}.energy-reading{display:flex;justify-content:space-between;align-items:center;font-size:12px}.energy-reading input{width:70px;padding:8px;border:1px solid #819478;background:#19322d;color:#dae2be}.energy-slider{width:100%;accent-color:#b4c48e;margin-top:18px}.energy-passed{font-size:22px;color:#bcdaaa;line-height:1.8}.energy-passed small{font-size:14px}.energy-empty{padding:35px;border:1px dashed #6e8b74;line-height:1.8;font-size:14px}.reduced-motion .energy-gauge-track i{transition:none}
@media(max-width:950px){.energy-bench{padding:24px}.energy-heading h2{font-size:21px}.energy-work-grid{grid-template-columns:minmax(0,1fr) 280px;gap:18px}.energy-object{height:180px}.energy-object>img{height:150px}.energy-profiles{gap:8px}.energy-profiles button{padding:12px}}
@media(max-width:600px){.energy-work-grid{grid-template-columns:1fr}.energy-profiles{grid-template-columns:1fr}.energy-heading{align-items:flex-start}.energy-heading>div:last-child{flex-direction:column;gap:8px}.energy-object{height:170px}.energy-controls{padding-top:0}}
@media(pointer:coarse){.energy-controls button,.energy-heading button,.energy-loads button{min-height:44px}}
</style>
